"use strict";(self.webpackChunkdg_knowlege_base=self.webpackChunkdg_knowlege_base||[]).push([[6472],{78491:e=>{e.exports=JSON.parse('{"tag":{"label":"Pipeline","permalink":"/docs/tags/pipeline","allTagsPath":"/docs/tags","count":19,"items":[{"id":"Lakehouse/About Lakehouse","title":"About Lakehouse","description":"Lakehouse is a hybrid data architecture, which provides a unified platform for storing diverse data (structured, semi-structured, unstructured) and performing advanced analytics. Key capabilities include:","permalink":"/docs/Lakehouse/about-lakehouse"},{"id":"Lakehouse/Pipelines/About pipelines","title":"About pipelines","description":"Data pipeline is a structured workflow that facilitates the movement and transformation of data from various data sources into your central warehouse and also in another data source. A pipeline can be compared to a conveyor belt that picks up data, performs specific actions on it, and then deposits it in its designated location.","permalink":"/docs/Lakehouse/Pipelines/about-pipelines"},{"id":"Lakehouse/Orchestrations/Adding members to an orchestration","title":"Adding members to an orchestration","description":"You can add users to an orchestration. If they do not already have access to associated pipelines, they can be granted permissions. Only Lakehouse members can be added, and they will receive creator permissions by default.","permalink":"/docs/Lakehouse/Orchestrations/adding-members-to-orchestration"},{"id":"Lakehouse/Agent Ops","title":"Agent Ops","description":"Agent ops is a feature designed for company administrators or super admins to monitor, manage, and analyze the usage and cost associated with your company\'s large language model (LLM) providers (e.g., OpenAI, Anthropic, Gemini).","permalink":"/docs/Lakehouse/agent ops"},{"id":"Lakehouse/Pipelines/Creating Custom pipeline","title":"Creating Custom pipeline","description":"1.  On the DataGOL Home page, from the left navigation panel, click Lakehouse > Pipelines.","permalink":"/docs/Lakehouse/Pipelines/creating-custom-pipeline"},{"id":"Lakehouse/Orchestrations/Creating orchestrations","title":"Creating orchestrations","description":"Orchestration in DataGOL allows you to define and manage the execution order of multiple pipelines. This is crucial when you have dependencies between pipelines, where one pipeline needs to complete successfully before another can begin. Without orchestration, scheduling pipelines to run independently might lead to failures or unexpected results if a dependent pipeline runs before its required data is ready.","permalink":"/docs/Lakehouse/Orchestrations/creating-orchestration"},{"id":"Lakehouse/Pipelines/Creating Standard pipeline","title":"Creating Standard pipeline","description":"1.  On the DataGOL Home page, from the left navigation panel, click Lakehouse > Pipelines.","permalink":"/docs/Lakehouse/Pipelines/creating-standard-pipeline-link"},{"id":"Lakehouse/Orchestrations/Deleting an orchestration","title":"Deleting an orchestration","description":"To delete an orchestration, do the following:","permalink":"/docs/Lakehouse/Orchestrations/deleting-an-orchestration"},{"id":"Lakehouse/Orchestrations/Editing an orchestration","title":"Editing an orchestration","description":"To edit an orchestration, do the following:","permalink":"/docs/Lakehouse/Orchestrations/editing-an-orchestration"},{"id":"Lakehouse/Jobs","title":"Jobs","description":"Navigate to Jobs: Under the Lakehouse section, go to Jobs.","permalink":"/docs/Lakehouse/jobs"},{"id":"Lakehouse/Orchestrations/Managing orchestrations","title":"Managing orchestrations","description":"You can manage and monitor the orchestrations from the Orchestrations page. The main Orchestration page display a list of all created orchestrations.","permalink":"/docs/Lakehouse/Orchestrations/managing-orchestration"},{"id":"Lakehouse/Pipelines/Managing pipeline","title":"Managing pipeline","description":"You can manage and monitor the pipelines from the Pipelines page.","permalink":"/docs/Lakehouse/Pipelines/managing-pipeline"},{"id":"Lakehouse/Pipelines/Pipeline details","title":"Pipeline details","description":"Click the link of a pipeline in the Pipeline list for a detailed view.","permalink":"/docs/Lakehouse/Pipelines/pipeline-details"},{"id":"Lakehouse/Pipelines/Pipeline sync modes","title":"Pipeline sync modes","description":"While creating a pipelilne, you can choose any of the following sync mode options:","permalink":"/docs/Lakehouse/Pipelines/pipeline-sync-modes"},{"id":"Lakehouse/Orchestrations/Running an orchestration","title":"Running an orchestration","description":"1.  On the DataGOL Home page, from the left navigation panel, click Lakehouse > Orchestration. The list of created orchestrations is displayed.","permalink":"/docs/Lakehouse/Orchestrations/running-an-orchestration"},{"id":"Lakehouse/Orchestrations/Updating the orchestration settings","title":"Updating the orchestration settings","description":"1.  On the DataGOL Home page, from the left navigation panel, click Lakehouse > Orchestration.","permalink":"/docs/Lakehouse/Orchestrations/updating-the-orchestration-settings"},{"id":"Lakehouse/Orchestrations/Viewing pipeline details of an orchestration","title":"Viewing pipeline details of an orchestration","description":"From the Pipelines tab of an orchestration, you can view the specifics of each pipeline within an orchestration. Click a pipeline link to access its comprehensive details, including its data source and destination. Furthermore, you can find information about the pipeline\'s creator and its designated stage order. For granular insights, the status and job stage details are readily available. To explore the data lineage, scroll right and click the more options icon.","permalink":"/docs/Lakehouse/Orchestrations/viewing-pipeline-details-of-an-orchestration"},{"id":"Lakehouse/Orchestrations/Viewing the orchestration graph","title":"Viewing the orchestration graph","description":"The Graphs tab within an orchestration provides a clear visual representation of the pipeline\'s execution order, illustrating the sequence of stages. To view the orchestration graph do the following:","permalink":"/docs/Lakehouse/Orchestrations/viewing-the-orchestration-graph"},{"id":"Lakehouse/Orchestrations/Viewing the orchestration run details","title":"Viewing the orchestration run details","description":"The Runs tab provides a comprehensive view of each orchestration execution. Here, you can readily see details such as the run\'s name, the user who initiated it, the start and end times, the total duration, and the current status (e.g., completed, failed). To investigate data lineage, click the more options icon. Additionally, clicking the View Snapshot link offers a detailed, point-in-time overview of that specific run.","permalink":"/docs/Lakehouse/Orchestrations/viewing-the-orchestration-run-details"}],"unlisted":false}}')}}]);